/* Lot 95: registered values computed in the reader sheet with the page viewport (generated by scripts/lot95_propgen.py; expectations from lot95_propmodel.py). */
#include "../../framework/unity.h"
#include <string.h>
#include <stdio.h>
#include "wf_sitecss.h"

static wf_site_t g_d;
static char g_html[4096], g_t[256];

static void prep(const char *css, int vw, int vh) {
    snprintf(g_html, sizeof(g_html), "<html><head><style>%s</style></head><body>"
             "<div id=o><p id=i>i</p></div><p id=q>q</p></body></html>", css);
    TEST_ASSERT_EQUAL(0, wf_site_prepare_ext(&g_d, g_html, (int)strlen(g_html), vw, vh, 0, 0));
    TEST_ASSERT_EQUAL(1, g_d.nprops);
}

static const char *nv(const char *id) {
    int i;
    for (i = 0; i < g_d.nnodes; i++)
        if (!strcmp(g_d.node[i].id, id)) { const char *v = wf_site_node_var(&g_d, i, "--p"); return v ? v : "(none)"; }
    return "(no node)";
}

static const char *tail(void) {
    const char *s;
    wf_site_props_text(&g_d, g_t, (int)sizeof(g_t));
    s = strstr(g_t, " simplified ");
    return s ? s : "";
}

static void test_l95_sheet_0(void) {
    prep("@property --p { syntax: '<resolution>+'; inherits: false; initial-value: 1dppx } #o { --p: 96dppx calc(5.282dpi + -100dpi) 216.2dpi } #i { --p: 2dpcm calc(-365x + -363.4998x / 90.7) }", 375, 812);
    TEST_ASSERT_EQUAL_STRING("96dppx -0.9867dppx 2.2521dppx", nv("o"));
    TEST_ASSERT_EQUAL_STRING("0.0529dppx -369.0077dppx", nv("i"));
    TEST_ASSERT_EQUAL_STRING("1dppx", nv("q"));
    TEST_ASSERT_EQUAL_STRING(" simplified 2", tail());
}

